---@field GoodNodeStub                  	UnityEngine.RectTransform               	@ 0    
---@field StatusLock                    	UnityEngine.RectTransform               	@ 1    
local CommonChooseRewardCell = Class("CommonChooseRewardCell")
local GoodsNodeMBPath = 'Game.Behaviours.GoodNodeMB'
local KTool = CS.Engine.Lib.KTool
local ReverseScaleType = typeof(CS.Game.Native.Common.ReverseScale)

function CommonChooseRewardCell:__init()
    self.data = nil
    self.index = nil
    self.callBack = nil
end

function CommonChooseRewardCell:__delete()
    self.data = nil
    self.index = nil
    self.callBack = nil
    self.controller = nil
end

function CommonChooseRewardCell:Awake()
    CfUtils.SetActive(self.StatusLock.gameObject,false)
end

function CommonChooseRewardCell:SetCellCallBack(cb)
    self.callBack = cb
end

function CommonChooseRewardCell:RefreshShow(data, index)
    self.data = data
    self.index = index
    if self.data.isLockItem then
        CfUtils.SetActive(self.StatusLock.gameObject,true)
    else
        CfUtils.SetActive(self.StatusLock.gameObject,false)
    end
    self:RefreshGoodNodeShow(self.data)
end

function CommonChooseRewardCell:RefreshGoodNodeShow(data)
    if isNull(self.GoodNode) then
        self.GoodNode = self.GoodNodeStub:InstantiatePrefab("GoodNode")
        local rect = self.GoodNode.gameObject:GetComponent("RectTransform")
        rect.pivot = Vector2.New(0.5, 0.5)
        rect.anchoredPosition = Vector3.New(0, 0, 0)
        rect.anchorMax = Vector2.New(0.5, 0.5)
        rect.anchorMin = Vector2.New(0.5, 0.5)
        CfUtils.SetActive(self.GoodNode.gameObject, true)
    end

    ---存在该节点将 父节点的缩放丢到该节点上
    ---@type Game.Native.Common.ReverseScale
    local reScaleComp = KTool.GetComponent(self.GoodNode.gameObject, ReverseScaleType)
    if isNotNull(reScaleComp) then
        reScaleComp.scale = 1
        reScaleComp:ResetScale()
    end

    self.goodNodeMB = CfUtils.GetLuaScr(self.GoodNode, GoodsNodeMBPath)
    self.goodNodeMB:Reload({ isShowNo = true , goodsId = data.goodsId, num = data.num, text = "x"..data.num})
    self.goodNodeMB:SetClickCallback(Bind(self, self.OnGridCellClickAction))
end

function CommonChooseRewardCell:OnGridCellClickAction()
    if self.data.isLockItem then
        GameUtils.Toast(self.data.LockDesc)
    end

    self.goodNodeMB:SetCheckState(true)
    if self.callBack then
       self.callBack(self.index)
    end
end

function CommonChooseRewardCell:SetSelectState(state)
    if isNotNull(self.goodNodeMB) then
        self.goodNodeMB:SetCheckState(state)
    end
end

function CommonChooseRewardCell:OnDestroy()
    self.controller = nil --删除lua层引⽤到的c#对象否则不会产⽣c# gc回收到对象
    self:Delete()
end

return CommonChooseRewardCell